 const metadata=roundPetMetadata({package:{hash_recipe:'pet-package-v1-canonical-json',sha256:P,content},catalog:{...m,sha256:P},sourceSha256,hash:sha256,approval:{schema_version:1,profile:'round-pet-native360/1',namespace:NATIVE360.namespace,firmware_package_sha256:P,hub_manifest_sha256:manifestDigest(m),source_manifest_sha256:sourceSha256,action_ids:m.actions.map(a=>a.id),license_ref:m.license_ref,approval_id:'original-pull-v1',credits:['original MIT test vector'],source_kind:'original-test',usage:'offline-validation'}});
